update public.asgc_content set data='{"blocks": {"paragraph_1": "Abuja, Nigeria \u00b7 Est. 2024", "heading_2": "Ahmed Sule Global Centre", "heading_3": "for Diplomacy, Trade", "paragraph_4": "Connecting Nations. Advancing Trade. Inspiring Investment.", "paragraph_5": "An independent, nonpartisan, nonprofit organisation advancing international cooperation, inclusive economic development and peaceful relations through diplomacy, trade and responsible investment.", "heading_6": "A Centre for International Cooperation and Sustainable Development", "paragraph_7": "The Ahmed Sule Global Centre for Diplomacy, Trade and Investment is conceived as an independent, nonpartisan, nonprofit organisation dedicated to advancing international cooperation, inclusive economic development and peaceful relations.", "paragraph_8": "Through research, capacity building and strategic partnerships, ASGC delivers measurable public benefit to Nigeria, Africa and the global community.", "paragraph_9": "\"Connecting Nations. Advancing Trade. Inspiring Investment.\"", "heading_10": "Three Pillars of ASGC", "paragraph_11": "\"A peaceful, connected and prosperous global community where cooperation creates inclusive opportunities and shared progress.\"", "paragraph_12": "To serve Nigeria, Africa and the global community by advancing diplomatic dialogue, inclusive trade and responsible investment through research, capacity building and strategic partnerships that deliver measurable public benefit.", "heading_13": "Six Areas of Mandate", "paragraph_14": "ASGC''s mandate guides every programme, publication and partnership the Centre undertakes.", "paragraph_20": "Whether you are a government institution, university, business, development organisation or diaspora network, ASGC welcomes purposeful partnerships that serve the public good.", "heading_21": "and Investment", "heading_22": "Our Vision", "heading_23": "Our Mission", "heading_24": ".", "heading_25": "News & Insights", "heading_26": "Upcoming Events", "heading_27": "Partner With ASGC"}, "arrays": {"mandateItems": [{"icon": "\ud83e\udd1d", "title": "Advance Diplomacy & Dialogue", "desc": "Convening diplomatic missions, public institutions and civil society to address shared challenges and strengthen international cooperation."}, {"icon": "\ud83d\udce6", "title": "Promote Inclusive Trade", "desc": "Research, knowledge sharing and programmes helping entrepreneurs and small businesses access regional and international opportunities."}, {"icon": "\ud83d\udcbc", "title": "Encourage Responsible Investment", "desc": "Connecting development needs with partners committed to ethical practices, job creation and community benefit."}, {"icon": "\ud83d\udcca", "title": "Support Informed Policymaking", "desc": "Independent research, policy dialogue and publications on diplomacy, trade, investment and sustainable development."}, {"icon": "\ud83c\udf93", "title": "Build Skills & Leadership", "desc": "Training, mentorship and exchanges in negotiation, economic diplomacy and entrepreneurship, particularly for young people and women."}, {"icon": "\ud83c\udf10", "title": "Develop Strategic Partnerships", "desc": "Working with universities, development organisations, diplomatic institutions, diaspora networks and the private sector."}], "items_2": [{"title": "Diplomacy", "img": "https://images.unsplash.com/photo-1633095975779-fd354aa0dc95?w=800&h=600&fit=crop&auto=format", "desc": "Convening diplomatic missions, governments, institutions and civil society to address shared challenges and strengthen international cooperation across Nigeria and Africa.", "to": "/our-work"}, {"title": "Trade", "img": "https://images.unsplash.com/photo-1739298061740-5ed03045b280?w=800&h=600&fit=crop&auto=format", "desc": "Undertaking research, knowledge sharing and programmes that help entrepreneurs and small businesses access regional and international trade opportunities.", "to": "/our-work"}, {"title": "Investment", "img": "https://images.unsplash.com/photo-1739298061707-cefee19941b7?w=800&h=600&fit=crop&auto=format", "desc": "Connecting development needs with partners committed to ethical practices, job creation, environmental responsibility and community benefit.", "to": "/our-work"}]}, "values": {"heroImg": "https://images.unsplash.com/photo-1590274853856-f22d5ee3d228?w=1800&h=900&fit=crop&auto=format", "meetingImg": "https://images.unsplash.com/photo-1739298061707-cefee19941b7?w=800&h=600&fit=crop&auto=format", "diplomacyImg": "https://images.unsplash.com/photo-1633095975779-fd354aa0dc95?w=800&h=600&fit=crop&auto=format", "tradeImg": "https://images.unsplash.com/photo-1739298061740-5ed03045b280?w=800&h=600&fit=crop&auto=format"}}'::jsonb where kind='page' and slug='home';
update public.asgc_content set data='{"blocks": {"paragraph_1": "An independent, nonpartisan, nonprofit organisation advancing international cooperation and inclusive development.", "heading_2": "Our Identity and Purpose", "paragraph_3": "The Ahmed Sule Global Centre for Diplomacy, Trade and Investment \u2014 known by its acronym ASGC, or AS Global Centre \u2014 is an independent, nonpartisan, nonprofit organisation based in Abuja, Nigeria.", "paragraph_4": "ASGC is dedicated to advancing international cooperation, inclusive economic development and peaceful relations through diplomacy, trade and responsible investment. The Centre serves Nigeria, Africa and the global community.", "paragraph_5": "Founded by Ambassador Ahmed Sule, a senior career diplomat with extensive international experience, ASGC draws on deep knowledge of how governments work, how international relationships develop and how diplomatic engagement can support national and economic priorities.", "paragraph_6": "\"A peaceful, connected and prosperous global community where cooperation creates inclusive opportunities and shared progress.\"", "paragraph_7": "To serve Nigeria, Africa and the global community by advancing diplomatic dialogue, inclusive trade and responsible investment through research, capacity building and strategic partnerships that deliver measurable public benefit.", "paragraph_8": "Nonprofit Commitment", "paragraph_9": "The Centre shall apply its income, grants, donations and any programme surplus solely to its mission and objectives. No profit or surplus shall be distributed to its founders, trustees or members. Its activities shall be guided by integrity, accountability, independence and service to the public.", "heading_10": "About ASGC", "heading_11": "Vision", "heading_12": "Mission", "heading_13": "Core Values"}, "arrays": {"coreValues": [{"icon": "\u2696\ufe0f", "title": "Integrity", "desc": "Honesty, transparency and ethical conduct in all our work."}, {"icon": "\ud83d\udccb", "title": "Accountability", "desc": "Responsible stewardship of trust, resources and relationships."}, {"icon": "\ud83c\udfdb\ufe0f", "title": "Independence", "desc": "Free from partisan, commercial or political interference."}, {"icon": "\ud83c\udf0d", "title": "Public Service", "desc": "Committed to the public good of Nigeria, Africa and the world."}, {"icon": "\ud83e\udd1d", "title": "Cooperation", "desc": "Building bridges across nations, institutions and communities."}, {"icon": "\ud83d\udca1", "title": "Excellence", "desc": "Pursuing the highest standards in research, dialogue and delivery."}], "items_1": [{"label": "Full Name", "val": "Ahmed Sule Global Centre for Diplomacy, Trade and Investment"}, {"label": "Acronym", "val": "ASGC \u2014 Ahmed Sule Global Centre"}, {"label": "Short Brand Name", "val": "AS Global Centre"}, {"label": "Type", "val": "Independent, Nonpartisan, Nonprofit Organisation"}, {"label": "Headquarters", "val": "Abuja, Nigeria"}, {"label": "Service Area", "val": "Nigeria, Africa and the Global Community"}]}, "values": {}}'::jsonb where kind='page' and slug='about';
update public.asgc_content set data='{"blocks": {"heading_1": "Our Mandate & Our Work", "paragraph_2": "Six areas of mandate guiding every programme, publication and partnership ASGC undertakes.", "heading_3": "Get Involved in Our Work", "paragraph_4": "Whether as a partner, participant, funder or collaborator \u2014 ASGC welcomes engagement from institutions, businesses, scholars and individuals committed to diplomacy, trade and responsible investment."}, "arrays": {"mandateAreas": [{"num": "01", "icon": "\ud83e\udd1d", "title": "Advance Diplomacy and Dialogue", "desc": "Convene diplomatic missions, public institutions, business leaders, scholars and civil society to address shared challenges and strengthen international cooperation.", "activities": ["High-level diplomatic dialogue forums", "Bilateral and multilateral roundtables", "Track II diplomacy initiatives", "Conflict prevention and peacebuilding discussions", "Government-to-government engagement support"], "img": "https://images.unsplash.com/photo-1590274853856-f22d5ee3d228?w=700&h=450&fit=crop&auto=format"}, {"num": "02", "icon": "\ud83d\udce6", "title": "Promote Inclusive Trade", "desc": "Undertake research, knowledge sharing and programmes that help entrepreneurs and small businesses understand and access regional and international opportunities.", "activities": ["Trade facilitation workshops and training", "Research on regional trade frameworks (AfCFTA)", "SME capacity building for export readiness", "Trade missions and business matching", "Policy briefings on trade corridors"], "img": "https://images.unsplash.com/photo-1739298061740-5ed03045b280?w=700&h=450&fit=crop&auto=format"}, {"num": "03", "icon": "\ud83d\udcbc", "title": "Encourage Responsible Investment", "desc": "Connect development needs with partners committed to ethical practices, job creation, environmental responsibility and community benefit.", "activities": ["Investment promotion events and forums", "Responsible investment frameworks and guidelines", "Investor-community engagement dialogues", "Environmental and social governance seminars", "Development finance partnership facilitation"], "img": "https://images.unsplash.com/photo-1739298061707-cefee19941b7?w=700&h=450&fit=crop&auto=format"}, {"num": "04", "icon": "\ud83d\udcca", "title": "Support Informed Policymaking", "desc": "Produce independent research, policy dialogue and publications on diplomacy, trade, investment and sustainable development.", "activities": ["Policy briefs and research papers", "Expert consultations and think-tank roundtables", "Engagement with government ministries and agencies", "Evidence-based policy recommendations", "Scholarly publications and reports"], "img": "https://images.unsplash.com/photo-1633095975779-fd354aa0dc95?w=700&h=450&fit=crop&auto=format"}, {"num": "05", "icon": "\ud83c\udf93", "title": "Build Skills and Leadership", "desc": "Provide training, mentorship and exchanges in negotiation, economic diplomacy, entrepreneurship and international engagement, particularly for young people and women.", "activities": ["Economic diplomacy training programmes", "Negotiation skills workshops", "Youth and women leadership development", "Mentorship schemes with experienced diplomats", "International exchange programmes"], "img": "https://images.unsplash.com/photo-1739285452644-3a2c009112fe?w=700&h=450&fit=crop&auto=format"}, {"num": "06", "icon": "\ud83c\udf10", "title": "Develop Strategic Partnerships", "desc": "Work with universities, development organisations, diplomatic institutions, diaspora networks and the private sector to implement programmes serving the public good.", "activities": ["University research collaboration agreements", "Development organisation programme partnerships", "Diplomatic institution exchanges", "Diaspora network engagement", "Private sector CSR programme delivery"], "img": "https://images.unsplash.com/photo-1590274853856-f22d5ee3d228?w=700&h=450&fit=crop&auto=format"}]}, "values": {}}'::jsonb where kind='page' and slug='our-work';
update public.asgc_content set data='{"blocks": {"paragraph_3": "Former High Commissioner of Nigeria to India, Bangladesh, Sri Lanka and Nepal", "paragraph_4": "Ambassador Ahmed Sule is a senior career diplomat with experience in foreign policy, economic diplomacy and high-level international engagement. His career encompasses ministerial advisory responsibilities, overseas assignments and participation in major bilateral and multilateral forums.", "paragraph_5": "He brings an understanding of how governments work, how international relationships develop and how diplomatic engagement can support national and economic priorities \u2014 providing the substantive foundation for ASGC''s focus on diplomacy, trade and investment.", "heading_9": "Professional Enquiries", "paragraph_10": "For professional engagements, speaking invitations, diplomatic enquiries or partnership discussions with Ambassador Ahmed Sule, please contact the ASGC office.", "heading_11": "Career Profile", "heading_12": "Executive Profile", "heading_13": "Career Timeline"}, "arrays": {"timelineItems": [{"period": "Early Career", "title": "Entry into the Diplomatic Service", "items": ["Third Secretary, Second Secretary \u2014 Federal Ministry of Foreign Affairs, Abuja", "First Secretary \u2014 Diplomatic postings at Nigerian Mission, Riyadh, Saudi Arabia", "Counsellor \u2014 New Delhi, India"]}, {"period": "Overseas Service", "title": "International Postings", "items": ["Riyadh, Saudi Arabia", "New Delhi, India", "Dhaka, Bangladesh", "Kathmandu, Nepal", "Colombo, Sri Lanka", "Ottawa, Canada", "London, United Kingdom", "Permanent Mission of Nigeria to the United Nations, New York, USA"]}, {"period": "Senior Leadership", "title": "Ministerial and Senior Advisory Roles", "items": ["Special Assistant on Diplomacy and Foreign Relations to the Honourable Minister of Foreign Affairs", "Personal Assistant to the Honourable Minister of State for Foreign Affairs", "Director of Protocol \u2014 Office of the First Lady of the Federal Republic of Nigeria", "Director \u2014 Middle East and Gulf Division", "Deputy Director for Industry, Trade and Investment", "Assistant Director for European Affairs"]}, {"period": "Economic Diplomacy", "title": "Investment Promotion & Bilateral Outcomes", "items": ["During the G20 Summit in New Delhi, facilitated investment pledges valued at approximately US$14 billion across priority sectors through diplomatic engagement, strategic liaison and investment promotion", "Contributed to the diplomatic work surrounding the State Visit of President Bola Ahmed Tinubu to Qatar, including the signing of eight bilateral agreements and Memoranda of Understanding in Doha", "Supported Nigeria''s international legal and diplomatic engagement in the P&ID matter as part of the wider efforts associated with the Federal Government''s successful defence before the Commercial Court in London", "Served on the Nigeria-India Joint Trade and Investment Commission in New Delhi (2001)"]}, {"period": "United Nations", "title": "International Security & UN Engagement", "items": ["Served at the Permanent Mission of Nigeria to the United Nations, New York", "Participated in UN Security Council matters and international security discussions", "Engaged in multilateral negotiations and diplomatic processes at the United Nations"]}, {"period": "Foundation", "title": "Establishment of ASGC", "items": ["Founded the Ahmed Sule Global Centre for Diplomacy, Trade and Investment (ASGC) in Abuja, Nigeria", "Appointed Founder and Chief Executive Officer of ASGC", "Launched ASGC''s programmes across diplomacy, trade, investment, policy research and capacity building"]}], "achievementCards": [{"title": "US$14 Billion", "sub": "Investment facilitation", "desc": "Facilitated investment pledges during the G20 Summit in New Delhi across priority sectors."}, {"title": "8 Bilateral Agreements", "sub": "Qatar State Visit", "desc": "Contributed to diplomatic work surrounding the signing of agreements and MoUs in Doha."}, {"title": "8 Countries", "sub": "Diplomatic postings", "desc": "Served at Nigerian missions across Asia, Europe, North America and the United Nations."}, {"title": "UN New York", "sub": "Multilateral diplomacy", "desc": "Represented Nigeria at the Permanent Mission to the United Nations in New York."}]}, "values": {}}'::jsonb where kind='page' and slug='founder';
