update public.asgc_content set data='{"blocks": {"paragraph_1": "The ASGC team welcomes enquiries from governments, institutions, businesses, scholars and the public.", "paragraph_2": "Life Camp, Abuja, Nigeria", "paragraph_3": "Complete the form below and a member of the ASGC team will respond promptly.", "paragraph_4": ". We will respond to your message within 3\u20135 working days.", "heading_5": "Contact ASGC", "heading_6": "Send a Message", "heading_7": "Message Sent"}, "arrays": {"departments": ["General Enquiry", "Programme Participation", "Media & Press", "Partnership Enquiry", "Research & Publications", "Ambassador Ahmed Sule \u2013 Professional Enquiry", "Other"]}, "values": {}}'::jsonb where kind='page' and slug='contact';
update public.asgc_content set data='{"blocks": {"heading_1": "Strategic Partnerships", "paragraph_2": "ASGC works with universities, development organisations, diplomatic institutions, diaspora networks and the private sector to implement programmes serving the public good.", "paragraph_3": "ASGC''s organisational mandate specifically identifies the following as partnership areas.", "paragraph_4": "How We Work Together", "heading_5": "Collaboration Opportunities", "paragraph_6": "ASGC welcomes purposeful partnerships that serve the public good. Partnership arrangements are structured around mutual benefit, shared values and measurable outcomes. The following forms of collaboration are currently available.", "heading_7": "ASGC Partnership Approach", "paragraph_8": "All ASGC partnerships are guided by the Centre''s core values of integrity, accountability, independence and public service. Prospective partners are welcome to initiate a conversation using the enquiry form on this page.", "paragraph_9": "Submit an enquiry and a member of the ASGC team will be in contact.", "paragraph_10": "Thank you for your interest in partnering with ASGC. We will respond to your enquiry within 5 working days.", "heading_11": "Partnership Areas", "heading_12": "Partner With ASGC", "heading_13": "Enquiry Received"}, "arrays": {"partnerTypes": [{"icon": "\ud83c\udfdb\ufe0f", "title": "Diplomatic Institutions", "desc": "Foreign missions, high commissions, consulates and diplomatic training institutions. ASGC welcomes structured engagement with diplomatic institutions to advance shared priorities in international cooperation."}, {"icon": "\ud83c\udf93", "title": "Universities & Research Institutions", "desc": "ASGC partners with universities and research institutions to co-produce knowledge, host scholars, support research programmes and deliver academic exchanges in diplomacy, trade and development."}, {"icon": "\ud83c\udf0d", "title": "Development Organisations", "desc": "International development organisations, multilateral agencies and NGOs working on economic development, trade facilitation, investment promotion and governance are priority partners for ASGC."}, {"icon": "\ud83c\udf10", "title": "Diaspora Networks", "desc": "Nigerian and African diaspora organisations and networks are integral to ASGC''s mission. The Centre engages diaspora communities as connectors, investors, advocates and contributors to homeland development."}, {"icon": "\ud83d\udcbc", "title": "Private Sector", "desc": "Businesses, industry associations, investors and entrepreneurs committed to ethical practices, job creation and community benefit are welcomed as ASGC programme partners and collaborators."}, {"icon": "\ud83e\udd1d", "title": "Civil Society", "desc": "Non-governmental organisations, think tanks, advocacy groups and community organisations contribute perspectives essential to ASGC''s inclusive approach to diplomacy, trade and investment."}], "opportunities": ["Programme co-design and joint delivery", "Research and policy collaboration", "Event co-sponsorship and hosting", "Staff exchanges and fellowships", "Joint publications and knowledge products", "Funding and philanthropic support", "Mentorship and capacity building", "Advocacy and policy engagement"], "items_1": ["Aligned values and public benefit orientation", "Clear shared objectives and expected outcomes", "Mutual commitment of time, expertise or resources", "Accountability and transparency in programme delivery"]}, "values": {}}'::jsonb where kind='page' and slug='partnerships';
